			function validationCheck() {
			    var dmSrvcPvsnRqst = app.lookup("dmSrvcPvsnRqst");
			    var chk = true;
			    // alert(dmSrvcPvsnRqst.getValue("RQST_TRPR_INFO_NO"));
			    if ("" == dmSrvcPvsnRqst.getValue("RQST_TRPR_INFO_NO") || null == dmSrvcPvsnRqst.getValue("RQST_TRPR_INFO_NO")) {
			        util.Msg.alert(app, "대상자명을 선택해 주세요.");
			        chk = false;
			        return chk;
			    }
			    
			    if ("" == dmSrvcPvsnRqst.getValue("RCPT_RQST_COURS_SE_CD")|| null == dmSrvcPvsnRqst.getValue("RCPT_RQST_COURS_SE_CD")) {
			        util.Msg.alert(app, "의뢰경로구분을 선택해 주세요.");
			        util.Control.setFocus(app, "comSearchInput2");
			        chk = false;
			        return chk;
			    }
			    
			    if ("" == dmSrvcPvsnRqst.getValue("CLINT_NO") || null == dmSrvcPvsnRqst.getValue("CLINT_NO")) {
			        util.Msg.alert(app, "의뢰담당자명을 선택해 주세요.");
			        chk = false;
			        return chk;
			    }
			    
			    // 의뢰 내용
			    var rqstDtlCn = dmSrvcPvsnRqst.getValue("RQST_DTL_CN");
			    var rqstDtlCnLen = (new TextEncoder().encode(rqstDtlCn)).length;
			    if (rqstDtlCnLen > 4000) {
			        var msg = "의뢰 내용의 길이가 " + rqstDtlCnLen + " byte 로서 입력 최대 길이인 4000 byte 를 초과합니다.";
			        msg += "\n영문자, 숫자는 1 byte, 한글은 한 글자가 3 byte 입니다.";
			        msg += "\n의뢰 내용의 길이를 조정해주시기 바랍니다.";
			        
			        util.Msg.alert(app, msg);
			        chk = false;
			        return chk;
			    }
			    
			    if ("" == dmSrvcPvsnRqst.getValue("RCPT_INST_NO") || null == dmSrvcPvsnRqst.getValue("RCPT_INST_NO")) {
			        util.Msg.alert(app, "단위업무구분 및 의뢰대상기관을 선택 해주세요");
			        chk = false;
			        return chk;
			    }
			    // 2022.12.30 대상기관 담당자 제거. 강화영 매니저님 요청 
			    /*
			    if ("" == dmSrvcPvsnRqst.getValue("CLR_NO") || null == dmSrvcPvsnRqst.getValue("CLR_NO")) {
			        util.Msg.alert(app, "의뢰대상기관 담당자를 선택해 주세요.");
			        chk = false;
			        return chk;
			    }
			    */
			    return chk;
			}

